161	void generate_rope_embed_cache_vision_mrope_interleaved(int seqlen,
162	                                                        int embed_dim,
163	                                                        int position_id,
164	                                                        int image_pad_index,
165	                                                        int image_embeds_size,
166	                                                        int num_patches_w,
167	                                                        ncnn::Mat& cos_cache,
168	                                                        ncnn::Mat& sin_cache,
169	                                                        float rope_theta)
170	{
171	    const int merge_size = 2;
172	    const int mrope[3] = {11, 11, 10};
173	    const float partial_rotary_factor = 0.5f;
174	    const int rotate_dim = embed_dim * partial_rotary_factor;
175	
176	    std::vector<float> inv_freq(rotate_dim / 2);
177	    for (int i = 0; i < rotate_dim / 2; i++)
178	    {
179	        inv_freq[i] = 1.f / powf(rope_theta, (float)(i * 2) / rotate_dim);
180	    }
181	
182	    cos_cache.create(embed_dim / 2, seqlen);
183	    sin_cache.create(embed_dim / 2, seqlen);
184	
185	    for (int i = 0; i < seqlen; i++)
186	    {
187	        float* cos_ptr = cos_cache.row(i);
188	        float* sin_ptr = sin_cache.row(i);
189	
190	        for (int j = 0; j < embed_dim / 2; j++)
191	        {
192	            if (j < rotate_dim / 2)
193	            {
194	                int pos = position_id;
195	                if (i < image_pad_index)
196	                {
197	                    pos += i;
198	                }
199	                else if (i >= image_pad_index + image_embeds_size)
200	                {
201	                    pos += i - image_embeds_size + (num_patches_w / merge_size);
202	                }
203	                else
204	                {
205	                    int which_pos = 0;
206	
207	                    if (j < mrope[1] * 3 && (j % 3 == 1))
208	                    {
209	                        which_pos = 1;
210	                    }
211	                    else if (j < mrope[2] * 3 && (j % 3 == 2))
212	                    {
213	                        which_pos = 2;
214	                    }
215	
216	                    if (which_pos == 0)
217	                    {
218	                        pos += image_pad_index;
219	                    }
220	                    else if (which_pos == 1)
221	                    {
222	                        int hid = (i - image_pad_index) / (num_patches_w / merge_size);
223	                        pos += image_pad_index + hid;
224	                    }
225	                    else
226	                    {
227	                        int wid = (i - image_pad_index) % (num_patches_w / merge_size);
228	                        pos += image_pad_index + wid;
229	                    }
230	                }
231	
232	                const float t = pos * inv_freq[j];
233	                const float cos_val = cosf(t);
234	                const float sin_val = sinf(t);
235	                *cos_ptr++ = cos_val;
236	                *sin_ptr++ = sin_val;
237	            }
238	            else
239	            {
240	                *cos_ptr++ = 1.0f;
241	                *sin_ptr++ = 0.0f;
242	            }
243	        }
244	    }
245	}
