252	void generate_rope_embed_cache_LongRoPE(int seqlen,
253	                                      int embed_dim,
254	                                      int position_id,
255	                                      ncnn::Mat& cos_cache,
256	                                      ncnn::Mat& sin_cache,
257	                                      float rope_theta,
258	                                      const float* SHORT_FACTOR,
259	                                      const float* LONG_FACTOR,
260	                                      int ORIGINAL_MAX_POSITION_EMBEDDINGS)
261	{
262	    if (embed_dim % 2 != 0 || seqlen <= 0) {
263	        cos_cache.release();
264	        sin_cache.release();
265	        return;
266	    }
267	
268	    const int half_dim = embed_dim / 2;
269	
270	    cos_cache.create(half_dim, seqlen);
271	    sin_cache.create(half_dim, seqlen);
272	
273	    if (cos_cache.empty() || sin_cache.empty()) {
274	        return;
275	    }
276	
277	    float* cos_ptr = cos_cache.channel(0);
278	    float* sin_ptr = sin_cache.channel(0);
279	
280	    std::vector<float> inv_freq(half_dim);
281	    for (int j = 0; j < half_dim; ++j) {
282	        float exponent = (2.0f * j) / static_cast<float>(embed_dim);
283	        inv_freq[j] = 1.0f / std::pow(rope_theta, exponent);
284	    }
285	
286	    const float* ext_factor = (seqlen > ORIGINAL_MAX_POSITION_EMBEDDINGS) ? LONG_FACTOR : SHORT_FACTOR;
287	    const float scaling_factor = compute_scaling_factor(ORIGINAL_MAX_POSITION_EMBEDDINGS);
288	
289	    for (int i = 0; i < seqlen; ++i) {
290	        int t = position_id + i;
291	        float* row_cos = cos_ptr + i * half_dim;
292	        float* row_sin = sin_ptr + i * half_dim;
293	
294	        for (int j = 0; j < half_dim; ++j) {
295	            float freq = (static_cast<float>(t) * inv_freq[j]) / ext_factor[j];
296	            row_cos[j] = std::cos(freq) * scaling_factor;
297	            row_sin[j] = std::sin(freq) * scaling_factor;
298	        }
299	    }
300	}
