302	void inject_image_embeds(std::vector<int>& token_ids, ncnn::Mat& token_embed, int& image_pad_index, int image_pad_id, const ncnn::Mat& image_embeds)
303	{
304	    image_pad_index = -1;
305	    if (image_embeds.empty())
306	    {
307	        return;
308	    }
309	
310	    std::vector<int> token_ids_injected(token_ids.size() - 1 + image_embeds.h);
311	    ncnn::Mat token_embed_injected(token_embed.w, token_embed.h - 1 + image_embeds.h);
312	
313	    for (int i = 0; i < (int)token_ids.size(); i++)
314	    {
315	        if (token_ids[i] == image_pad_id)
316	        {
317	            image_pad_index = i;
318	
319	            // inject token ids
320	            memcpy(token_ids_injected.data(), token_ids.data(), i * sizeof(int));
321	            memset(token_ids_injected.data() + i, image_pad_id, image_embeds.h * sizeof(int));
322	            memcpy(token_ids_injected.data() + i + image_embeds.h, token_ids.data() + i + 1, (token_ids.size() - 1 - i) * sizeof(int));
323	
324	            // inject token embed
325	            memcpy(token_embed_injected.row(0), token_embed.row(0), i * token_embed.w * sizeof(float));
326	            memcpy(token_embed_injected.row(i), image_embeds.row(0), image_embeds.h * token_embed.w * sizeof(float));
327	            memcpy(token_embed_injected.row(i + image_embeds.h), token_embed.row(i + 1), (token_ids.size() - 1 - i) * token_embed.w * sizeof(float));
328	
329	            break;
330	        }
331	    }
332	
333	    token_ids = token_ids_injected;
334	    token_embed = token_embed_injected;
335	}
