337	void generate_rope_embed_cache_vision_mrope(int seqlen, 
338	                                          int embed_dim, 
339	                                          int position_id, 
340	                                          int image_pad_index, 
341	                                          int image_embeds_size, 
342	                                          int num_patches_w, 
343	                                          int spatial_merge_size,
344	                                          const std::vector<int>& mrope_section,
345	                                          ncnn::Mat& cos_cache, 
346	                                          ncnn::Mat& sin_cache, 
347	                                          float rope_theta)
348	{
349	    if (mrope_section.size() < 3) return;
350	
351	    std::vector<float> inv_freq(embed_dim / 2);
352	    for (int i = 0; i < embed_dim / 2; i++)
353	    {
354	        inv_freq[i] = 1.f / powf(rope_theta, (float)(i * 2) / embed_dim);
355	    }
356	
357	    cos_cache.create(embed_dim / 2, seqlen);
358	    sin_cache.create(embed_dim / 2, seqlen);
359	
360	    for (int i = 0; i < seqlen; i++)
361	    {
362	        float* cos_ptr = cos_cache.row(i);
363	        float* sin_ptr = sin_cache.row(i);
364	
365	        for (int j = 0; j < embed_dim / 2; j++)
366	        {
367	            int pos = position_id;
368	            if (i < image_pad_index)
369	            {
370	                pos += i;
371	            }
372	            else if (i >= image_pad_index + image_embeds_size)
373	            {
374	                pos += i - image_embeds_size + (num_patches_w / spatial_merge_size);
375	            }
376	            else
377	            {
378	                // inside image tokens range
379	                if (j < mrope_section[0])
380	                {
381	                    // temporal
382	                    pos += image_pad_index;
383	                }
384	                else if (j < mrope_section[0] + mrope_section[1])
385	                {
386	                    // height
387	                    int hid = (i - image_pad_index) / (num_patches_w / spatial_merge_size);
388	                    pos += image_pad_index + hid;
389	                }
390	                else
391	                {
392	                    // width
393	                    int wid = (i - image_pad_index) % (num_patches_w / spatial_merge_size);
394	                    pos += image_pad_index + wid;
395	                }
396	            }
397	
398	            const float t = pos * inv_freq[j];
399	            const float cos_val = cosf(t);
400	            const float sin_val = sinf(t);
401	            *cos_ptr++ = cos_val;
402	            *sin_ptr++ = sin_val;
403	        }
404	    }
405	}
406	void generate_hunyuan_xdrope_cos_sin(const std::vector<int>* pos4,
407	                                     int seq_len,
408	                                     int rope_head_dim,
409	                                     const std::vector<int>& xdrope_section,
410	                                     float rope_theta,
411	                                     float alpha,
412	                                     ncnn::Mat& cos_cache,
413	                                     ncnn::Mat& sin_cache) {
414	    const int half = rope_head_dim / 2;
415	    cos_cache.create(half, seq_len);
416	    sin_cache.create(half, seq_len);
417	
418	    // NTK-alpha base: base = rope_theta * alpha^(head_dim/(head_dim-2))
419	    const double base_corr = std::pow((double)alpha,
420	                                      (double)rope_head_dim / ((double)rope_head_dim - 2.0));
421	    const double ntk_theta = (double)rope_theta * base_corr;
422	
423	    std::vector<float> inv_freq(half);
424	    for (int j = 0; j < half; j++) {
425	        inv_freq[j] = (float)(1.0 / std::pow(ntk_theta, (double)(2 * j) / (double)rope_head_dim));
426	    }
427	
428	    // axis index per dim, from the (possibly unequal) section widths
429	    std::vector<int> axis_of_dim(half, (int)xdrope_section.size() - 1);
430	    {
431	        int d = 0;
432	        for (int a = 0; a < (int)xdrope_section.size() && d < half; a++) {
433	            for (int s = 0; s < xdrope_section[a] && d < half; s++) {
434	                axis_of_dim[d++] = a;
435	            }
436	        }
437	    }
438	
439	    for (int i = 0; i < seq_len; i++) {
440	        float* cos_ptr = cos_cache.row(i);
441	        float* sin_ptr = sin_cache.row(i);
442	        for (int j = 0; j < half; j++) {
443	            const int a = axis_of_dim[j];
444	            const float pos = (float)pos4[a][i];
445	            const float t = pos * inv_freq[j];
446	            cos_ptr[j] = cosf(t);
447	            sin_ptr[j] = sinf(t);
448	        }
449	    }
450	}
